package app.repositories

import app.common.Page
import app.entities.Author
import java.util.UUID

/** Keeps authors rows in memory, for tests and for trying the services without a database. */
class MemoryAuthorRepository : AuthorRepository {
    private val rows = linkedMapOf<List<Any?>, Author>()

    /** The key of a row, as a list of its key values. */
    private fun keyOf(row: Author): List<Any?> = listOf(row.id)

    /** Orders two keys value by value. */
    @Suppress("UNCHECKED_CAST")
    private fun compareKeys(a: List<Any?>, b: List<Any?>): Int {
        for (index in a.indices) {
            val order = compareValues(a[index] as Comparable<Any>?, b[index] as Comparable<Any>?)
            if (order != 0) return order
        }
        return 0
    }

    private fun visible(): List<Author> =
        rows.values.filter { true }.sortedWith { a, b -> compareKeys(keyOf(a), keyOf(b)) }

    override fun findById(id: UUID): Author? {
        return visible().firstOrNull { it.id == id }
    }

    override fun list(offset: Int, limit: Int): Page<Author> {
        val rows = visible()
        return Page(rows.drop(offset).take(limit), rows.size.toLong(), offset, limit)
    }

    override fun insert(entity: Author): Author {
        rows[keyOf(entity)] = entity
        return entity
    }

    override fun update(entity: Author): Author {
        rows[keyOf(entity)] = entity
        return entity
    }

    override fun delete(entity: Author): Unit {
        rows.remove(keyOf(entity))
    }
}

