        return entity
    }

    override fun update(entity: Post): Post {
        rows[keyOf(entity)] = entity
        return entity
    }

    override fun delete(entity: Post): Unit {
        rows.remove(keyOf(entity))
    }

    override fun addComment(id: UUID, comment: Post.Comment): Post? {
        val found = visible().firstOrNull { it.id == id } ?: return null
        found.comments = found.comments.orEmpty() + listOf(comment)
        return found
    }

    override fun removeComment(id: UUID, position: Int, size: Int): Post? {
        val found = visible().firstOrNull { it.id == id } ?: return null
        if (found.comments.orEmpty().size != size) return null
        found.comments = found.comments.orEmpty().filterIndexed { index, _ -> index != position }
        return found
    }
}

