package app.repositories

import app.Db
import app.Documents
import app.common.Page
import app.entities.Author
import java.util.Collections
import java.util.UUID
import java.util.WeakHashMap
import org.bson.Document

/** Keeps authors rows in the database, through the MongoDB driver. Every write is stored at once. */
class MongoAuthorRepository(private val db: Db) : AuthorRepository {
    private val collection = "authors"

    /** The fields a change may write */
    private val fields = listOf("email")

    override fun findById(id: UUID): Author? {
        return db.find(collection, Document("_id", id), limit = 1).firstOrNull()?.let { loaded(it) }
    }

    override fun list(offset: Int, limit: Int): Page<Author> {
        val items = if (limit > 0) db.find(collection, Document(), sort = Document("_id", 1), skip = offset, limit = limit).map { loaded(it) } else emptyList()
        return Page(items, db.count(collection, Document()), offset, limit)
    }

    override fun insert(entity: Author): Author {
        db.insert("Author", collection, toDocument(entity))
        READ[entity] = Documents.copy(toDocument(entity)) as Document
        return entity
    }

    override fun update(entity: Author): Author {
        val now = toDocument(entity)
        val changes = Documents.changes(READ[entity], now, fields)
        if (changes.isNotEmpty()) {
            db.update("Author", collection, Document("_id", now["_id"]), changes)
        }
        READ[entity] = Documents.copy(now) as Document
        return entity
    }

    override fun delete(entity: Author): Unit {
        db.delete("Author", collection, Document("_id", entity.id!!))
    }

    /** The entity of a document, with the document kept to tell its changes. */
    private fun loaded(document: Document): Author {
        val entity = fromDocument(document)
        READ[entity] = Documents.copy(toDocument(entity)) as Document
        return entity
    }

    /** The document of a Author: what is null is left out. */
    private fun toDocument(value: Author): Document {
        val document = Document()
        value.id?.let { document["_id"] = it }
        value.email?.let { document["email"] = it }
        return document
    }

    private fun fromDocument(document: Document): Author =
        Author(
            id = document["_id"] as UUID?,
            email = document["email"] as String?,
        )

    private companion object {
        /** The document each entity was read from: a change writes only the fields that differ */
        val READ: MutableMap<Author, Document> = Collections.synchronizedMap(WeakHashMap())
