package app.repositories

import app.Db
import app.Documents
import app.common.Page
import app.entities.Post
import java.util.Collections
import java.util.Date
import java.util.UUID
import java.util.WeakHashMap
import org.bson.Document

/** Keeps posts rows in the database, through the MongoDB driver. Every write is stored at once. */
class MongoPostRepository(private val db: Db) : PostRepository {
    private val collection = "posts"

    /** The fields a change may write */
    private val fields = listOf("title", "author", "published_at", "comments")

    override fun findById(id: UUID): Post? {
        return db.find(collection, Document("_id", id), limit = 1).firstOrNull()?.let { loaded(it) }
    }

    override fun list(offset: Int, limit: Int): Page<Post> {
        val items = if (limit > 0) db.find(collection, Document(), sort = Document("_id", 1), skip = offset, limit = limit).map { loaded(it) } else emptyList()
        return Page(items, db.count(collection, Document()), offset, limit)
    }

    override fun listByAuthor(author: UUID): List<Post> {
        return db.find(collection, Document("author", author), sort = Document("_id", 1)).map { loaded(it) }
    }

    override fun insert(entity: Post): Post {
        db.insert("Post", collection, toDocument(entity))
        READ[entity] = Documents.copy(toDocument(entity)) as Document
        return entity
    }

    override fun update(entity: Post): Post {
        val now = toDocument(entity)
        val changes = Documents.changes(READ[entity], now, fields)
        if (changes.isNotEmpty()) {
            db.update("Post", collection, Document("_id", now["_id"]), changes)
        }
        READ[entity] = Documents.copy(now) as Document
        return entity
    }

    override fun delete(entity: Post): Unit {
        db.delete("Post", collection, Document("_id", entity.id!!))
    }

    override fun addComment(id: UUID, comment: Post.Comment): Post? {
        val change = Document("\$push", Document("comments", commentToDocument(comment)))
        return db.change("Post", collection, Document("_id", id), change)?.let { loaded(it) }
    }

    override fun removeComment(id: UUID, position: Int, size: Int): Post? {
        val head = Document("\$slice", listOf("\$comments", position))
        val tail = Document("\$slice", listOf("\$comments", position + 1, maxOf(size, 1)))
        val change = listOf(Document("\$set", Document("comments", Document("\$concatArrays", listOf(head, tail)))))
        return db.rewrite("Post", collection, Document("_id", id).append("comments", Document("\$size", size)), change)?.let { loaded(it) }
    }

    /** The entity of a document, with the document kept to tell its changes. */
    private fun loaded(document: Document): Post {
        val entity = fromDocument(document)
        READ[entity] = Documents.copy(toDocument(entity)) as Document
        return entity
    }

    /** The document of a Post: what is null is left out. */
    private fun toDocument(value: Post): Document {
        val document = Document()
        value.id?.let { document["_id"] = it }
        value.title?.let { document["title"] = it }
        value.author?.let { document["author"] = it }
        value.publishedAt?.let { document["published_at"] = Date.from(it) }
        value.comments?.let { held -> document["comments"] = held.map { commentToDocument(it) } }
        return document
    }

    private fun fromDocument(document: Document): Post =
        Post(
            id = document["_id"] as UUID?,
            title = document["title"] as String?,
            author = document["author"] as UUID?,
            publishedAt = (document["published_at"] as Date?)?.toInstant(),
            comments = (document["comments"] as List<*>?)?.mapNotNull { (it as Document?)?.let { commentFromDocument(it) } },
        )

    /** The document of a Post.Comment: what is null is left out. */
    private fun commentToDocument(value: Post.Comment): Document {
        val document = Document()
        value.id?.let { document["id"] = it }
        value.text?.let { document["text"] = it }
        value.marks?.let { document["marks"] = it }
        return document
    }

    private fun commentFromDocument(document: Document): Post.Comment =
        Post.Comment(
            id = document["id"] as UUID?,
            text = document["text"] as String?,
            marks = (document["marks"] as List<*>?)?.mapNotNull { it as UUID? },
        )

    private companion object {
        /** The document each entity was read from: a change writes only the fields that differ */
        val READ: MutableMap<Post, Document> = Collections.synchronizedMap(WeakHashMap())
    }
}

