import app.errors.FieldError
import app.errors.NotFoundException
import app.errors.ValidationFailedException
import java.util.UUID

/** Operations on authors. Repositories commit every write. */
class AuthorService(private val unitOfWork: UnitOfWork) {
    /** Stores a new Author after checking it. */
    fun createAuthor(author: Author): Author {
        val values = mapOf(
            "id" to author.id,
            "email" to author.email,
        ).filterValues { it != null }
        return unitOfWork.transaction { uow ->
            checkValues(uow, values, null)
            uow.authors.insert(author)
        }
    }

    /** The Author with this key; NotFoundException when there is none. */
    fun getAuthor(id: UUID): Author = find(unitOfWork, id)

    /** A page of authors, by primary key. */
    fun listAuthors(offset: Int, limit: Int): Page<Author> = unitOfWork.authors.list(offset, limit)

    /** Changes the given values of a Author. */
    fun updateAuthor(id: UUID, changes: AuthorChanges): Author {
        val values = given(changes)
        return unitOfWork.transaction { uow ->
            val current = find(uow, id)
            checkValues(uow, values, current)
            applyValues(current, values)
            uow.authors.update(current)
        }
    }

    /** Deletes a Author. */
    fun deleteAuthor(id: UUID) {
        unitOfWork.transaction { uow ->
            val current = find(uow, id)
            if (uow.posts.listByAuthor(current.id!!).isNotEmpty())
                throw ConflictException("Author", "rows of posts still point to it", listOf("posts"))
            uow.authors.delete(current)
        }
    }

    /** Checks the values against the rules of the "authors" table, and the rows they point to; throws ValidationFailedException with every problem. */
    private fun validate(uow: UnitOfWork, values: Map<String, Any?>, current: Author?) {
        val creating = current == null
        val errors = mutableListOf<FieldError>()
        run {
            val value = values["id"]
            if (value == null) {
                if (creating || "id" in values) errors += FieldError("_id", "is required")
            }
        }
        run {
            val value = values["email"]
            if (value == null) {
                if (creating || "email" in values) errors += FieldError("email", "is required")
            }
        }
        if (errors.isNotEmpty()) throw ValidationFailedException("Author", errors)
    }

    /** Every check before a write: the values, the rows they point to, the unique values. */
    private fun checkValues(uow: UnitOfWork, values: Map<String, Any?>, current: Author?) {
        validate(uow, values, current)
    }

    /** Sets the given values on the entity. */
    private fun applyValues(entity: Author, values: Map<String, Any?>) {
        if ("id" in values) entity.id = values["id"] as UUID?
        if ("email" in values) entity.email = values["email"] as String?
    }

    /** The Author with this key; NotFoundException when there is none. */
    private fun find(uow: UnitOfWork, id: UUID): Author =
        uow.authors.findById(id) ?: throw NotFoundException("Author", id)

    /** The values an update gives, by field. */
    private fun given(changes: AuthorChanges): Map<String, Any?> {
        val values = mutableMapOf<String, Any?>()
        if (changes.email.isPresent) values["email"] = changes.email.value
        return values
    }
}

