/** Operations on posts. Repositories commit every write. */
@Suppress("UNCHECKED_CAST")
class PostService(private val unitOfWork: UnitOfWork) {
    /** Stores a new Post after checking it. */
    fun createPost(post: Post): Post {
        val values = mapOf(
            "id" to post.id,
            "title" to post.title,
            "author" to post.author,
            "publishedAt" to post.publishedAt,
            "comments" to post.comments,
        ).filterValues { it != null }
        return unitOfWork.transaction { uow ->
            checkValues(uow, values, null)
            uow.posts.insert(post)
        }
    }

    /** The Post with this key; NotFoundException when there is none. */
    fun getPost(id: UUID): Post = find(unitOfWork, id)

    /** A page of posts, by primary key. */
    fun listPosts(offset: Int, limit: Int): Page<Post> = unitOfWork.posts.list(offset, limit)

    /** Changes the given values of a Post. */
    fun updatePost(id: UUID, changes: PostChanges): Post {
        val values = given(changes)
        return unitOfWork.transaction { uow ->
            val current = find(uow, id)
            checkValues(uow, values, current)
            applyValues(current, values)
            uow.posts.update(current)
        }
    }

    /** Deletes a Post. */
    fun deletePost(id: UUID) {
        unitOfWork.transaction { uow ->
            val current = find(uow, id)
            uow.posts.delete(current)
        }
    }

    /** The posts with this author. */
    fun listPostsByAuthor(author: UUID): List<Post> = unitOfWork.posts.listByAuthor(author)

    /** Adds an item to comments. */
    fun addComment(id: UUID, comment: Post.Comment): Post {
        val errors = mutableListOf<FieldError>()
        checkComment(comment, "comments", errors)
        if (errors.isNotEmpty()) throw ValidationFailedException("Post", errors)
        return unitOfWork.transaction { uow ->
            find(uow, id)
            uow.posts.addComment(id, comment) ?: throw NotFoundException("Post", id)
        }
    }

    /** Removes an item from comments, by its position. */
    fun removeComment(id: UUID, position: Int): Post {
        return unitOfWork.transaction { uow ->
            val current = find(uow, id)
            if (position !in current.comments.orEmpty().indices) throw NotFoundException("Comment", position)
            uow.posts.removeComment(id, position, current.comments.orEmpty().size) ?: throw ConflictException("Post", "was changed by someone else since it was read", listOf("comments"))
        }
    }

    /** Checks the values against the rules of the "posts" table, and the rows they point to; throws ValidationFailedException with every problem. */
    private fun validate(uow: UnitOfWork, values: Map<String, Any?>, current: Post?) {
        val creating = current == null
        val errors = mutableListOf<FieldError>()
        run {
            val value = values["id"]
            if (value == null) {
                if (creating || "id" in values) errors += FieldError("_id", "is required")
            }
        }
        run {
            val value = values["title"]
            if (value == null) {
                if (creating || "title" in values) errors += FieldError("title", "is required")
            }
        }
        run {
            val value = values["author"]
            if (value == null) {
                if (creating || "author" in values) errors += FieldError("author", "is required")
            }
        }
        run {
            val value = values["comments"]
            if (value == null) {
                if (creating || "comments" in values) errors += FieldError("comments", "is required")
            } else {
                val document = value as List<Post.Comment>
                document.forEachIndexed { i0, item0 ->
                    checkComment(item0, "comments" + "." + i0, errors)
                }
            }
        }
        run {
            val author = if ("author" in values) values["author"] as UUID? else current?.author
            if (author != null && uow.authors.findById(author) == null)
                errors += FieldError("author", "no Author has this key")
        }
        if (errors.isNotEmpty()) throw ValidationFailedException("Post", errors)
    }

    /** Every check before a write: the values, the rows they point to, the unique values. */
    private fun checkValues(uow: UnitOfWork, values: Map<String, Any?>, current: Post?) {
        validate(uow, values, current)
    }

    /** Sets the given values on the entity. */
    private fun applyValues(entity: Post, values: Map<String, Any?>) {
        if ("id" in values) entity.id = values["id"] as UUID?
        if ("title" in values) entity.title = values["title"] as String?
        if ("author" in values) entity.author = values["author"] as UUID?
        if ("publishedAt" in values) entity.publishedAt = values["publishedAt"] as Instant?
        if ("comments" in values) entity.comments = values["comments"] as List<Post.Comment>?
    }

    /** The Post with this key; NotFoundException when there is none. */
    private fun find(uow: UnitOfWork, id: UUID): Post =
        uow.posts.findById(id) ?: throw NotFoundException("Post", id)

    /** The values an update gives, by field. */
    private fun given(changes: PostChanges): Map<String, Any?> {
        val values = mutableMapOf<String, Any?>()
        if (changes.title.isPresent) values["title"] = changes.title.value
        if (changes.author.isPresent) values["author"] = changes.author.value
        if (changes.publishedAt.isPresent) values["publishedAt"] = changes.publishedAt.value
        if (changes.comments.isPresent) values["comments"] = changes.comments.value
        return values
    }

    /** What a Post.Comment does not follow of its rules, each with the path of its field. */
    private fun checkComment(value: Post.Comment, path: String, errors: MutableList<FieldError>) {
        if (value.id == null) errors += FieldError(path + ".id", "is required")
        if (value.text == null) errors += FieldError(path + ".text", "is required")
        if (value.marks == null) errors += FieldError(path + ".marks", "is required")
    }
}

